"""Export SDLC artifacts (generated by the real agents) into the repository's sdlc/ folder.

    cd backend && python -m app.sdlc_engine.export
"""

from __future__ import annotations

import json
from pathlib import Path

from app.config.settings import PROJECT_DIR


def main() -> None:
    from app.agents.registry import register_all
    from app.graphs.sdlc_graph import DEMO_REQUIREMENT
    from app.sdlc_engine import architecture, qa, rca, requirements
    from app.tools.patient_tools import register

    register_all()
    register()
    out = PROJECT_DIR / "sdlc"

    def w(rel: str, data) -> None:
        p = out / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(data if isinstance(data, str) else json.dumps(data, indent=2, default=str))

    w("requirements/demo-requirement-analysis.json", requirements.analyze(DEMO_REQUIREMENT))
    md = ["# Architecture diagrams (generated)\n", "Regenerate with `python -m app.sdlc_engine.export`.\n"]
    for d in architecture.all_diagrams().values():
        md.append(f"\n## {d['title']}\n\n```mermaid\n{d['mermaid']}\n```\n")
    w("architecture/diagrams.md", "".join(md))
    for b in ("1.4.0", "1.5.0", "1.5.1"):
        w(f"qa/scenario-report-{b}.json", qa.run_suite(b))
    res = rca.analyze(None, "1.5.0")
    w("monitoring/rca-build-1.5.0.json", res)
    w("development/fix-1.5.1.json", rca.propose_fix("1.5.0"))
    print(f"exported to {Path(out)}")


if __name__ == "__main__":
    main()
